{
  "name": "arch-governance-opencode",
  "version": "0.1.1",
  "description": "Enterprise architecture governance plugin for OpenCode — auto-triggering architecture review, diagnosis, and audit across project stages. Works standalone; cooperates with oh-my-openagent when present.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist",
    ".opencode",
    ".agents",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "architecture",
    "governance",
    "compliance",
    "enterprise",
    "ai-application",
    "audit",
    "clean-architecture",
    "code-review"
  ],
  "license": "MIT",
  "author": "ericccc98",
  "repository": {
    "type": "git",
    "url": "https://github.com/Eric980212/arch-governance-opencode.git",
    "directory": "packages/arch-governance-opencode"
  },
  "homepage": "https://github.com/Eric980212/arch-governance-opencode#readme",
  "bugs": {
    "url": "https://github.com/Eric980212/arch-governance-opencode/issues"
  },
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun --format esm --external @opencode-ai/plugin && tsc --emitDeclarationOnly --outDir dist",
    "prepublishOnly": "bun run build",
    "clean": "if (Test-Path dist) { Remove-Item -Recurse -Force dist }"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.15.13"
  },
  "devDependencies": {
    "typescript": "^5.7.0",
    "bun-types": "^1.3.0"
  },
  "peerDependenciesMeta": {
    "oh-my-openagent": {
      "optional": true
    }
  }
}
